// The editor's control catalogue: web/src/generated/controls.js (generated by fotufilm-controls
// from Sources/FotufilmEditModel/EditorControlCatalogue.swift), staged as JSON by tool/prepare.sh,
// and the web editor's own slider list (web/src/editor-state.js) and profile rules
// (web/src/profile-settings.js), which this file follows rule for rule.
import 'dart:convert';

import 'package:flutter/services.dart';

typedef Json = Map<String, dynamic>;

class SliderSpec {
  const SliderSpec({
    required this.key,
    required this.label,
    required this.min,
    required this.max,
    required this.step,
    required this.def,
    this.unit = '',
    this.group = '',
    this.detail,
    this.availability,
    this.stops = const [],
  });

  final String key, label, unit, group;
  final double min, max, step, def;
  final String? detail, availability;
  final List<double> stops;
}

class Catalogue {
  Catalogue._(this.module);

  final Json module;

  static Future<Catalogue> load() async =>
      Catalogue._(jsonDecode(await rootBundle.loadString('assets/generated/controls.json')) as Json);

  List<Json> get controls => (module['EDITOR_CONTROLS'] as List).cast<Json>();
  List<Json> get filmFormats => (module['FILM_FORMATS'] as List).cast<Json>();
  Json get screenConversion => module['SCREEN_CONVERSION'] as Json;
  Json get profileMenus => module['PROFILE_MENUS'] as Json;

  Json control(String field) => controls.firstWhere((c) => c['field'] == field,
      orElse: () => throw StateError('Unknown editor control: $field'));

  String? detail(String field) {
    for (final c in controls) {
      if (c['field'] == field) return c['detail'] as String?;
    }
    return null;
  }

  static const _units = {
    'stops': 'EV',
    'stopsFromOff': 'EV',
    'years': 'yr',
    'kelvin': 'K',
    'multiplier': '×',
    'degrees': '°',
  };

  SliderSpec catalogueSlider(String field, String group, [double step = 0.01]) {
    final c = control(field);
    final scale = c['scale'] as Json;
    return SliderSpec(
      key: field,
      label: c['title'] as String,
      detail: c['detail'] as String?,
      availability: c['availability'] as String?,
      group: group,
      step: step,
      min: (scale['min'] as num).toDouble(),
      max: (scale['max'] as num).toDouble(),
      def: (scale['neutral'] as num).toDouble(),
      unit: _units[scale['unit']] ?? '',
    );
  }

  /// The editor's own sliders, keyed as the edit's `params` (web/src/editor-state.js).
  late final List<SliderSpec> sliders = [
    catalogueSlider('cameraPreflash', 'Light', 0.005),
    catalogueSlider('sceneLightKelvin', 'Source Illuminant', 1),
    SliderSpec(key: 'ev', label: 'Exposure', min: -3, max: 3, step: .05, def: 0, unit: 'EV',
        group: 'Light', detail: detail('exposure')),
    SliderSpec(key: 'highlights', label: 'Highlights', min: -1, max: 1, step: .01, def: 0,
        group: 'Light', detail: detail('highlights')),
    SliderSpec(key: 'shadows', label: 'Shadows', min: -1, max: 1, step: .01, def: 0,
        group: 'Light', detail: detail('shadows')),
    SliderSpec(key: 'temperature', label: 'Temperature', min: 2000, max: 12000, step: 1,
        def: 6504, unit: 'K', group: 'White Balance'),
    SliderSpec(key: 'tint', label: 'Tint', min: -100, max: 100, step: 1, def: 0,
        group: 'White Balance', detail: detail('tint')),
    SliderSpec(key: 'saturation', label: 'Saturation', min: 0, max: 2, step: .01, def: 1,
        unit: '×', group: 'Color', detail: detail('saturation')),
    SliderSpec(key: 'vibrance', label: 'Vibrance', min: -1, max: 1, step: .01, def: 0,
        group: 'Color', detail: detail('vibrance')),
    SliderSpec(key: 'grain', label: 'Grain', min: 0, max: 2, step: .01, def: 1, unit: '×',
        group: 'Character', detail: detail('grain')),
    for (final band in const ['Shadows', 'Midtones', 'Highlights'])
      for (final axis in const ['Warmth', 'Tint', 'Level'])
        SliderSpec(key: 'grade$band$axis', label: axis, min: -1, max: 1, step: .01, def: 0,
            group: band),
  ];

  // ── Profile controls (web/src/profile-settings.js) ──────────────────────────────────────

  late final List<Json> profileControls = [
    for (final c in controls)
      if (c['webTransform'] == 'profile')
        {...c, 'choices': c['choices'] ?? profileMenus[c['field']]},
  ];

  static Object? profileDefault(Json c) {
    final scale = c['scale'];
    if (scale is Map && scale['neutral'] != null) return scale['neutral'];
    final curve = c['curve'];
    if (curve is Map) return [for (final _ in curve['handles'] as List) curve['neutral']];
    if (c['kind'] == 'toggle') return c['restingOn'];
    final choices = c['choices'];
    if (choices is List && choices.isNotEmpty) return (choices.first as Map)['id'];
    return null;
  }

  static Json? profileMedium(Json edit, Json? stock) {
    final media = (stock?['profile'] as Map?)?['media'] as Map?;
    return media?[edit['medium'] ?? stock?['defaultMedium']] as Json?;
  }

  static Json profileControl(Json c, Json edit, Json? stock) {
    final medium = profileMedium(edit, stock);
    final profile = stock?['profile'] as Map?;
    return {
      ...c,
      'scale': (profile?['scales'] as Map?)?[c['field']] ?? c['scale'],
      'choices': c['field'] == 'printLight'
          ? (medium?['viewingLights'] ?? c['choices'])
          : ((profile?['choices'] as Map?)?[c['field']] ?? c['choices']),
    };
  }

  static bool profileControlAvailable(Json c, Json edit, Json? stock) {
    if (c['section'] == 'hdrHighlights') return true;
    final available = (stock?['available'] as List?) ?? const [];
    if (!available.contains(c['field'])) return false;
    final medium = profileMedium(edit, stock);
    bool flag(String key) => medium?[key] == true;
    if (c['section'] == 'printLamp') return flag('enlarger');
    switch (c['field']) {
      case 'printLight':
        return ((medium?['viewingLights'] as List?)?.length ?? 0) > 1;
      case 'screenExposure':
        return flag('screenConversion');
      case 'screenCyan' || 'screenMagenta' || 'screenYellow':
        return flag('screenCMY');
      case 'screenRedBand' || 'screenGreenBand' || 'screenBlueBand':
        return flag('receiverBands');
      case 'labScanDodging' || 'labScanLook':
        return flag('labScan');
      case 'printerRed' || 'printerGreen' || 'printerBlue':
        return flag('printerLights');
      case 'screenGrade':
        return flag('screenGrade') && edit['digitalReference'] != 'reference-exposure';
      case 'printCorrection':
        return flag('correction');
      case 'negativeViewing':
        return flag('negative');
      case 'filmGrainSize' || 'filmColourGrain' || 'filmRedLayer' || 'filmGreenLayer' ||
            'filmBlueLayer' || 'filmScanSoftness':
        return (edit['profile'] as Map?)?['grainModel'] == 'film';
      default:
        return true;
    }
  }

  Json profileRequestControls(Json edit, Json? stock) {
    final profile = (edit['profile'] as Map?) ?? const {};
    final out = <String, dynamic>{};
    for (final c in profileControls) {
      if (!profileControlAvailable(c, edit, stock) || !profile.containsKey(c['field'])) continue;
      final active = profileControl(c, edit, stock);
      final value = profile[c['field']];
      final field = c['field'] as String;
      final stops = ((active['scale'] as Map?)?['stops'] as List?) ?? const [];
      final choices = active['choices'] as List?;
      if (field == 'push' && !stops.contains(value)) {
        out[field] = 0;
      } else if (choices != null && !choices.any((choice) => (choice as Map)['id'] == value)) {
        out[field] = profileDefault(active);
      } else {
        out[field] = value;
      }
    }
    return out;
  }

  /// The controls of `fields` this film and medium offer, in catalogue order.
  List<Json> profileFields(List<String> fields, Json edit, Json? stock) => [
        for (final c in profileControls)
          if (fields.contains(c['field']) && profileControlAvailable(c, edit, stock))
            profileControl(c, edit, stock),
      ];

  /// The source illuminant the edit asks the film to be balanced for (editor-catalogue.js).
  num? sourceIlluminant(Json edit) {
    final choices = (control('sceneLight')['choices'] as List).cast<Json>();
    final choice = choices.firstWhere((c) => c['id'] == edit['sceneLight'],
        orElse: () => choices.first);
    if (choice['id'] == 'custom') return (edit['params'] as Map)['sceneLightKelvin'] as num?;
    final value = choice['value'] as num?;
    return value == null || value == 0 ? null : value;
  }

  // ── Slider glyphs ───────────────────────────────────────────────────────────────────────

  static const _sliderFields = {'ev': 'exposure', 'temperature': 'warmth'};
  static final _withoutEnds = RegExp(
      r'^grade(Shadows|Midtones|Highlights)|^(straighten|halationHaze|antiHalation|baseThickness|pressurePlate|screen(Red|Green|Blue)Band)$');

  late final Set<String> _ended = {
    for (final c in controls)
      if (c['kind'] == 'slider' && !_withoutEnds.hasMatch(c['field'] as String))
        c['field'] as String,
  };

  (String, String)? sliderEnds(String key) {
    final field = _sliderFields[key] ?? key;
    if (!_ended.contains(field)) return null;
    final low = 'fotu.slider.$field.low', high = 'fotu.slider.$field.high';
    return key == 'temperature' ? (high, low) : (low, high);
  }
}
